    def _appends(self, append: Mapping[str, Any], layer: str, file: Optional[str],
                 line_of: Callable[[Key], Optional[int]]) -> List[Tuple[Leaf, List[Any], Optional[int]]]:
        found: List[Tuple[Leaf, List[Any], Optional[int]]] = []

